public class Solution {
    private static double poly(long[] xs, double x) {
        double sum = 0.0;
        for (int i = 0; i < xs.length; i++) {
            sum += xs[i] * Math.pow(x, i);
        }
        return sum;
    }

    public static double find_zero(long[] a0) {
        double begin = -1.0;
        double end = 1.0;
        while (poly(a0, begin) * poly(a0, end) > 0.0) {
            begin *= 2.0;
            end *= 2.0;
        }
        while (end - begin > 1e-10) {
            double center = (begin + end) / 2.0;
            if (poly(a0, center) * poly(a0, begin) > 0.0) {
                begin = center;
            } else {
                end = center;
            }
        }
        return begin;
    }
}

