public class Solution {
    private static boolean is_prime(long k) {
        if (k < 2) {
            return false;
        }
        for (long i = 2; i <= k / i; i++) {
            if (k % i == 0) {
                return false;
            }
        }
        return true;
    }

    public static long largest_prime_factor(long a0) {
        if (a0 <= 1) {
            return 1;
        }
        long largest = 1;
        long temp = a0;
        for (long j = 2; j <= temp / j; j++) {
            if (temp % j == 0) {
                largest = j;
                while (temp % j == 0) {
                    temp /= j;
                }
            }
        }
        if (temp > 1) {
            largest = Math.max(largest, temp);
        }
        return largest;
    }
}

