public class Solution {
    public static long[] sort_array(long[] a0) {
        if (a0 == null) {
            return null;
        }
        Long[] boxed = new Long[a0.length];
        for (int i = 0; i < a0.length; i++) {
            boxed[i] = a0[i];
        }
        Arrays.sort(boxed, (x, y) -> {
            int c1 = countOnes(x);
            int c2 = countOnes(y);
            if (c1 != c2) {
                return Integer.compare(c1, c2);
            }
            return Long.compare(x, y);
        });
        long[] result = new long[a0.length];
        for (int i = 0; i < a0.length; i++) {
            result[i] = boxed[i];
        }
        return result;
    }

    private static int countOnes(long x) {
        if (x < 0) {
            if (x == Long.MIN_VALUE) {
                return 1;
            }
            return Long.bitCount(-x);
        }
        return Long.bitCount(x);
    }
}

