        long l = Math.max(a0[0], a1[0]);
        long r = Math.min(a0[1], a1[1]);
        long length = r - l;
        if (length > 0 && isPrime(length)) {
            return "YES";
        }
        return "NO";
    }

    private static boolean isPrime(long num) {
        if (num <= 1) {
            return false;
        }
        if (num == 2) {
            return true;
        }
        for (long i = 2; i <= num / i; i++) {
            if (num % i == 0) {
