            }
        }
        return true;
    }
}

public class Solution {
    public static long[] minPath(long[][] a0, long a1) {
        int n = a0.length;
        long val = (long) n * n + 1;
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                if (a0[i][j] == 1) {
                    long minVal = Long.MAX_VALUE;
                    if (i != 0) {
                        minVal = Math.min(minVal, a0[i - 1][j]);
                    }
                    if (j != 0) {
                        minVal = Math.min(minVal, a0[i][j - 1]);
                    }
                    if (i != n - 1) {
                        minVal = Math.min(minVal, a0[i + 1][j]);
                    }
                    if (j != n - 1) {
                        minVal = Math.min(minVal, a0[i][j + 1]);
                    }
                    val = minVal;
                }
            }
        }
        int k = (int) a1;
        long[] ans = new long[k];
        for (int i = 0; i < k; i++) {
            if (i % 2 == 0) {
                ans[i] = 1;
            } else {
                ans[i] = val;
            }
        }
        return ans;
    }
}

public class Solution {
    public static double[] tri(long a0) {
        if (a0 == 0) {
            return new double[]{1.0};
        }
        if (a0 < 0) {
            return new double[]{1.0, 3.0};
        }
        int n = (int) a0;
        double[] myTri = new double[n + 1];
        myTri[0] = 1.0;
        myTri[1] = 3.0;
        for (int i = 2; i <= n; i++) {
            if (i % 2 == 0) {
                myTri[i] = i / 2.0 + 1.0;
            } else {
                myTri[i] = myTri[i - 1] + myTri[i - 2] + (i + 3.0) / 2.0;
            }
        }
        return myTri;
    }
}

public class Solution {
    public static long digits(long a0) {
        long product = 1;
        int oddCount = 0;
        String s = String.valueOf(a0);
        for (int i = 0; i < s.length(); i++) {
            char c = s.charAt(i);
            if (Character.isDigit(c)) {
                int intDigit = c - '0';
                if (intDigit % 2 == 1) {
                    product *= intDigit;
                    oddCount++;
                }
            }
        }
        if (oddCount == 0) {
            return 0;
        } else {
            return product;
        }
    }
}

