import java.util.ArrayList;
import java.util.List;

public class Solution {
    public static long do_algebra(String[] a0, long[] a1) {
        if (a1 == null || a1.length == 0) {
            return 0L;
        }

        List<Long> operands = new ArrayList<>();
        for (long num : a1) {
            operands.add(num);
        }

        List<String> operators = new ArrayList<>();
        if (a0 != null) {
            for (String op : a0) {
                operators.add(op.trim());
            }
        }

        for (int i = operators.size() - 1; i >= 0; i--) {
            if (operators.get(i).equals("**")) {
                long base = operands.get(i);
                long exp = operands.get(i + 1);
                long val = power(base, exp);
                operands.set(i, val);
                operands.remove(i + 1);
                operators.remove(i);
            }
        }

        for (int i = 0; i < operators.size(); ) {
            String op = operators.get(i);
            if (op.equals("*") || op.equals("//") || op.equals("/") || op.equals("%")) {
                long left = operands.get(i);
                long right = operands.get(i + 1);
                long val = 0L;
                if (op.equals("*")) {
                    val = left * right;
                } else if (op.equals("//") || op.equals("/")) {
                    val = Math.floorDiv(left, right);
                } else if (op.equals("%")) {
                    val = Math.floorMod(left, right);
                }
                operands.set(i, val);
                operands.remove(i + 1);
                operators.remove(i);
            } else {
                i++;
            }
        }

        for (int i = 0; i < operators.size(); ) {
            String op = operators.get(i);
            if (op.equals("+") || op.equals("-")) {
                long left = operands.get(i);
                long right = operands.get(i + 1);
                long val = op.equals("+") ? (left + right) : (left - right);
                operands.set(i, val);
                operands.remove(i + 1);
                operators.remove(i);
            } else {
                i++;
            }
        }

        return operands.get(0);
    }

    private static long power(long base, long exp) {
        long res = 1;
        long b = base;
        long e = exp;
        while (e > 0) {
            if ((e & 1) == 1) {
                res *= b;
            }
            b *= b;
            e >>= 1;
        }
        return res;
    }
}

